<template>
  <div class="profile">
    <ProfileHeader :username="formattedAutoTitle" :uniqueCode="publication?.id" :goBack="goBack" :backIcon="backIcon" />
    <ProfileSwitcher :switcherItems="switcherItems" v-model:modelValue="selectedItem" />

    <div class="profile__wrapper">
      <component :is="currentComponent" :userId="route.params.id" />
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { getCarById } from '@/services/apiClient';
import backIcon from '@/assets/icons/back-wide.svg';

import PublicationInfoAdmin from '@/components/PUBLICATION/PublicationInfoAdmin.vue';
import PublicationStatistic from '@/components/PUBLICATION/PublicationStatistic.vue';
import PublicationHistory from '@/components/PUBLICATION/PublicationHistory.vue'; 
import PublicationServices from '@/components/PUBLICATION/PublicationServices.vue'; 

import ProfileHeader from '@/components/UI/CustomProfileHeader.vue';
import ProfileSwitcher from '@/components/UI/CustomProfileSwitcher.vue';

const route = useRoute();
const router = useRouter();
const publication = ref(null);
const loading = ref(true);

const switcherItems = ['Инфо', 'История', 'Услуги', 'Статистика'];
const selectedItem = ref(switcherItems[0]);

const fetchPublicationData = async () => {
  try {
    const response = await getCarById(route.params.id);
    publication.value = response;
  } catch (error) {
    console.error('Ошибка при получении данных объявления:', error);
    publication.value = null;
  } finally {
    loading.value = false;
  }
};

const goBack = () => {
  router.back();
};

const formattedAutoTitle = computed(() => {
  const autoSpecs = publication.value?.auto_technical_specifications?.[0];
  return `${autoSpecs?.brand?.title} ${autoSpecs?.model?.title} ${autoSpecs?.year_release?.title}`;
});

const currentComponent = computed(() => {
  switch (selectedItem.value) {
    case 'Инфо':
      return PublicationInfoAdmin;
    case 'История':
      return PublicationHistory;
    case 'Услуги':
      return PublicationServices;
    case 'Статистика':
      return PublicationStatistic;
    default:
      return PublicationInfoAdmin;
  }
});

onMounted(fetchPublicationData);
</script>

