<template>
   <div v-if="ad" class="ad-info">
      <div class="statistics-cards">
         <StatisticCard v-for="(card, index) in cards" :key="index" :icon="card.icon" :title="card.title"
            :views="card.views" :description="card.description" :isSelected="selectedCardIndex === index"
            @click="selectCard(index)" />
      </div>

      <PublicationChart />
      <InfoDetail label="Опубликовано" :value="`19.03.2024 | 21:23`" />
      <InfoDetail label="Время просмотра" :value="`29` + ' дней'" />
      <InfoDetail label="Среднее время на странице" :value="`28` + ' сек'" />
   </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRoute } from 'vue-router';
import { getCarById } from '@/services/apiClient';
import PublicationChart from '@/components/PUBLICATION/PublicationChart.vue';
import InfoDetail from '@/components/USER/InfoDetail.vue';
import StatisticCard from '@/components/PUBLICATION/StatisticCard.vue';

import eyeIcon from '@/assets/icons/eye.svg';
import eyeUIcon from '@/assets/icons/eye-u.svg';
import personIcon from '@/assets/icons/person.svg';
import favIcon from '@/assets/icons/fav.svg';

const ad = ref(null);
const route = useRoute();

const selectedCardIndex = ref(0);

const cards = [
   { icon: eyeIcon, title: 'Просмотры', views: 120, description: 'Общее число переходов на страницу объявления' },
   { icon: eyeUIcon, title: 'Уникальные', views: 250, description: 'Пользователей впервые посетивших страницу' },
   { icon: personIcon, title: 'Интересовавшиеся', views: 98, description: 'Пользователей, смотревших контакты продавца' },
   { icon: favIcon, title: 'В избранном', views: 450, description: 'Количество добавлений объявления в избранное' }
];

const selectCard = (index) => {
   selectedCardIndex.value = index;
};

const fetchAdData = async () => {
   try {
      const response = await getCarById(route.params.id);
      ad.value = response;
   } catch (error) {
      console.error('Ошибка при получении данных объявления:', error);
   }
};

onMounted(fetchAdData);
</script>

