   display: flex;
   flex-direction: column;
   gap: 16px;

   &__divider {
      height: 1px;
      background-color: #D6D6D6;
   }
}

.statistics-cards {
   display: flex;
   gap: 16px;
   margin: 24px 0;
   justify-content: flex-start;
   flex-wrap: wrap;
}
