<template>
   <div class="chart-container">
      <canvas ref="chartRef"></canvas>
   </div>
</template>

<script setup>
import { ref, watch, onMounted, defineProps } from 'vue';
import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

const chartRef = ref(null);
let chartInstance = null;

const props = defineProps({
   dataPoints: {
      type: Array,
      default: () => [
         { date: '2024-01-01', value: 10 },
         { date: '2024-01-05', value: 18 },
         { date: '2024-01-10', value: 25 },
         { date: '2024-01-15', value: 19 },
         { date: '2024-01-20', value: 30 },
         { date: '2024-01-25', value: 28 },
         { date: '2024-02-01', value: 35 },
         { date: '2024-02-05', value: 33 },
         { date: '2024-02-10', value: 40 },
         { date: '2024-02-15', value: 42 },
         { date: '2024-02-20', value: 39 },
         { date: '2024-02-25', value: 45 },
         { date: '2024-03-01', value: 50 },
      ]
   }
});

const createChart = () => {
   if (!chartRef.value) return;
   if (chartInstance) chartInstance.destroy();

   const ctx = chartRef.value.getContext('2d');

   chartInstance = new Chart(ctx, {
      type: 'line',
      data: {
         labels: props.dataPoints.map(point => {
            const d = new Date(point.date);
            return d.toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' });
         }),
         datasets: [{
            data: props.dataPoints.map(point => point.value),
            borderColor: '#3366FF',
            backgroundColor: 'rgba(51, 102, 255, 0.15)',
            tension: 0.3,
            fill: true,
            pointRadius: 4,
            pointBackgroundColor: 'rgba(51, 102, 255, 1)'
         }]
      },
      options: {
         responsive: true,
         maintainAspectRatio: false,
         plugins: {
            legend: { display: false }
         },
         scales: {
            x: {
               grid: { display: false },
               ticks: {
                  maxRotation: 0,
                  minRotation: 0
               }
            },
            y: {
               position: 'right',
               grid: { display: true },
               ticks: {
                  callback: value => value 
               }
            }
         }
      }
   });
};

watch(() => props.dataPoints, createChart, { deep: true });
onMounted(createChart);
</script>

<style scoped>
.chart-container {
   width: 100%;
   position: relative;
   margin-bottom: 8px;
}

canvas {
   width: 100% !important;
   max-height: 400px;
}
</style>