<template>
   <div v-if="ad" class="ad-info">
      <!-- Фото -->
      <div class="ad-info__photos">
         <div v-for="(photo, index) in ad.photos || []" :key="index" class="ad-info__photo">
            <img :src="getImageUrl(photo.arr_title_size.preview, avatarPhoto)" :alt="'Фото объявления ' + index"
               class="ad-info__image" />
         </div>
      </div>
      <InfoDetail label="Цена" :value="ad?.ads_parameter?.amount ? ad.ads_parameter.amount + ' ₽' : 'Не указана'" />
      <InfoDetail label="Описание" :value="ad?.ads_parameter?.ads_description || 'Описание отсутствует'" />
      <InfoDetail label="Пользователь" :value="ad?.ads_parameter?.username || 'Не указан'" />
      <InfoDetail label="Номер телефона" value="Не указан" />
      <InfoDetail label="Локация" :value="ad?.ads_parameter?.city?.title || 'Не указана'" />
      <InfoDetail label="Создано"
         :value="ad?.created_at ? new Date(ad.created_at).toLocaleDateString() : 'Неизвестно'" />
      <InfoDetail label="Изменено"
         :value="ad?.updated_at ? new Date(ad.updated_at).toLocaleDateString() : 'Неизвестно'" />
      <InfoDetail label="Текущий статус" :value="ad?.is_published ? 'Опубликовано' : 'Не опубликовано'" />
      <InfoDetail label="Продвижение" :value="ad?.is_promoted ? 'Продвигается' : 'Не продвигается'" />
      <InfoDetail label="Оформление" :value="ad?.is_formatted ? 'Оформлено' : 'Не оформлено'" />
   </div>
</template>


<script setup>
import { ref, onMounted } from 'vue';
import { useRoute } from 'vue-router';
import { getCarById } from '@/services/apiClient';
import { getImageUrl } from '@/services/imageUtils';
import InfoDetail from '../USER/InfoDetail.vue';
import avatarPhoto from "@/assets/icons/placeholder.png";

const ad = ref(null);
const route = useRoute();

const fetchAdData = async () => {
   try {
      const response = await getCarById(route.params.id);
      ad.value = response;
   } catch (error) {
      console.error('Ошибка при получении данных объявления:', error);
   }
};

onMounted(fetchAdData);
</script>

