   display: flex;
   flex-direction: column;
   gap: 16px;

   &__photos {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
   }

   &__photo {
      width: 120px;
      height: 120px;
   }

   &__image {
      width: 100%;
      height: 100%;
      object-fit: cover;
      border-radius: 8px;
   }

   &__divider {
      height: 1px;
      background-color: #D6D6D6;
   }
}
